    TEST_CHECK(gkyl_dynvec_get_tm(dv, i) == i * 0.1);
  }

  gkyl_dynvec_clear(dv);
  TEST_CHECK(gkyl_dynvec_size(dv) == 0);
  TEST_CHECK(gkyl_dynvec_getlast(dv, out) == false);

